import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
  });

  test('should display PayPal as a payment option', async ({ page }) => {
    const paypalOption = await page.getByText('PayPal');
    await expect(paypalOption).toBeVisible();
  });

  test('should select PayPal as the payment method', async ({ page }) => {
    await page.getByText('PayPal').click();
    const selectedPaymentMethod = await page.getByRole('button', { name: 'Continue to PayPal' });
    await expect(selectedPaymentMethod).toBeVisible();
    await selectedPaymentMethod.click();

    const paypalLoginPage = await page.url();
    expect(paypalLoginPage).toContain('paypal.com');
  });
});
